import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

max_reduce_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>
#include <vector>

__global__ void max_reduce_kernel(const float* __restrict__ input,
                                   float* __restrict__ output,
                                   long outer_size,
                                   long reduce_size,
                                   long inner_size) {
    long idx = blockIdx.x * (long)blockDim.x + threadIdx.x;
    long total = outer_size * inner_size;
    long stride = (long)blockDim.x * gridDim.x;
    for (; idx < total; idx += stride) {
        long outer_idx = idx / inner_size;
        long inner_idx = idx % inner_size;
        const float* base = input + outer_idx * reduce_size * inner_size + inner_idx;
        float max_val = -FLT_MAX;
        long i = 0;
        long unroll_end = reduce_size - (reduce_size % 4);
        #pragma unroll 4
        for (; i < unroll_end; i += 4) {
            float v0 = __ldg(&base[i * inner_size]);
            float v1 = __ldg(&base[(i + 1) * inner_size]);
            float v2 = __ldg(&base[(i + 2) * inner_size]);
            float v3 = __ldg(&base[(i + 3) * inner_size]);
            max_val = fmaxf(max_val, v0);
            max_val = fmaxf(max_val, v1);
            max_val = fmaxf(max_val, v2);
            max_val = fmaxf(max_val, v3);
        }
        for (; i < reduce_size; ++i) {
            float val = __ldg(&base[i * inner_size]);
            max_val = fmaxf(max_val, val);
        }
        output[idx] = max_val;
    }
}

torch::Tensor max_reduce_cuda(torch::Tensor input, int64_t dim) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    int ndim = input.dim();
    if (dim < 0) dim += ndim;
    TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");
    auto sizes = input.sizes();
    long outer_size = 1;
    for (int i = 0; i < dim; ++i) outer_size *= sizes[i];
    long reduce_size = sizes[dim];
    long inner_size = 1;
    for (int i = dim + 1; i < ndim; ++i) inner_size *= sizes[i];
    std::vector<int64_t> out_sizes;
    for (int i = 0; i < ndim; ++i) {
        if (i != dim) out_sizes.push_back(sizes[i]);
    }

    auto output = torch::empty(out_sizes, input.options());

    long total = outer_size * inner_size;
    int threads = 256;
    long blocks_l = (total + threads - 1) / threads;
    int blocks = (int)(blocks_l > 65535 ? 65535 : blocks_l);
    if (blocks < 1) blocks = 1;

    max_reduce_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        outer_size, reduce_size, inner_size
    );

    return output;
}
"""

max_reduce_cpp_source = "torch::Tensor max_reduce_cuda(torch::Tensor input, int64_t dim);"

max_reduce_module = load_inline(
    name="max_reduce_module",
    cpp_sources=max_reduce_cpp_source,
    cuda_sources=max_reduce_source,
    functions=["max_reduce_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs Max reduction over a specific dimension
    using a custom CUDA kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.max_reduce = max_reduce_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        return self.max_reduce.max_reduce_cuda(x, self.dim)


batch_size = 128
dim1 = 4096
dim2 = 4095

def get_inputs():
    x = torch.rand(batch_size, dim1, dim2)
    return [x]

def get_init_inputs():
    return [1]

